#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int zmiany = 0;
    int prevDir = 0;
    for (int i = 1; i < (int)dane.size(); i++) {
        int dir = 0;
        if (dane[i] > dane[i - 1]) dir = 1;
        else if (dane[i] < dane[i - 1]) dir = -1;
        if (dir != 0 && prevDir != 0 && dir != prevDir) zmiany++;
        if (dir != 0) prevDir = dir;
    }
    cout << "Liczba zmian kierunku: " << zmiany << endl;
    return 0;
}
```

Weryfikacja:
- Kierunki: +,+,-,-,+,+,-,-,+,+,-,+,-,-
- Zmiany: (++)→(--) pos3, (--)→(++) pos5, (++)→(--) pos7, (--)→(++) pos9, (++)→(-) pos11, (-)→(+) pos12, (+)→(--) pos13
- Razem: 7
